package org.apache.commons.lang3.math;

import java.io.*;
import java.lang.reflect.Array;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen0Test {

    @Test
    public void testCreateNumber_Null() {
        assertNull(NumberUtils.createNumber(null));
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_Blank() {
        NumberUtils.createNumber("   ");
    }

    @Test
    public void testCreateNumber_Integer() {
        Number n = NumberUtils.createNumber("123");
        assertTrue(n instanceof Integer);
        assertEquals(123, n.intValue());
    }

    @Test
    public void testCreateNumber_Long() {
        // A number larger than Integer.MAX_VALUE but fits in Long
        Number n = NumberUtils.createNumber("3000000000");
        assertTrue(n instanceof Long);
        assertEquals(3000000000L, n.longValue());
    }

    @Test
    public void testCreateNumber_BigInteger() {
        String huge = "123456789012345678901234567890";
        Number n = NumberUtils.createNumber(huge);
        assertTrue(n instanceof BigInteger);
        assertEquals(new BigInteger(huge), n);
    }

    @Test
    public void testCreateNumber_Float() {
        // numDecimals <= 7 logic
        Number n = NumberUtils.createNumber("1.2345");
        assertTrue(n instanceof Float);
        assertEquals(1.2345f, n.floatValue(), 0.0001f);
    }

    @Test
    public void testCreateNumber_Double() {
        // numDecimals between 8 and 16
        Number n = NumberUtils.createNumber("1.123456789");
        assertTrue(n instanceof Double);
        assertEquals(1.123456789, n.doubleValue(), 0.000000001);
    }

    @Test
    public void testCreateNumber_BigDecimal() {
        // numDecimals > 16
        Number n = NumberUtils.createNumber("1.1234567890123456789");
        assertTrue(n instanceof BigDecimal);
    }

    @Test
    public void testCreateNumber_WithExponent() {
        // Scientific notation triggers different logic
        Number n = NumberUtils.createNumber("1.23e2");
        assertEquals(123.0, n.doubleValue(), 0.001);
    }

    @Test
    public void testCreateNumber_SuffixL() {
        Number n = NumberUtils.createNumber("123L");
        assertTrue(n instanceof Long);
        assertEquals(123L, n.longValue());

        Number nBig = NumberUtils.createNumber("12345678901234567890L");
        assertTrue(nBig instanceof BigInteger);
    }

    @Test
    public void testCreateNumber_SuffixF() {
        Number n = NumberUtils.createNumber("123.45f");
        assertTrue(n instanceof Float);
    }

    @Test
    public void testCreateNumber_SuffixD() {
        Number n = NumberUtils.createNumber("123.45d");
        assertTrue(n instanceof Double);
    }

    @Test
    public void testCreateNumber_InvalidSuffix() {
        try {
            NumberUtils.createNumber("123x");
            fail("Should have thrown NumberFormatException");
        } catch (NumberFormatException e) {
            // Expected
        }
    }

    @Test
    public void testCreateNumber_InvalidFormat() {
        try {
            NumberUtils.createNumber("1.2.3");
            fail("Should have thrown NumberFormatException");
        } catch (NumberFormatException e) {
            // Expected
        }
    }

    @Test
    public void testCreateNumber_AllZerosCase() {
        // Tests the !allZeros logic for precision/zero checks
        Number n = NumberUtils.createNumber("0.000000000000000001");
        assertTrue(n instanceof BigDecimal);
    }

    @Test
    public void testCreateNumber_Negative() {
        Number n = NumberUtils.createNumber("-123");
        assertEquals(-123, n.intValue());
    }

    @Test
    public void testCreateNumber_HexPrefixes() {
        // Note: The code contains 'if (false)' for hex branch, 
        // so we test the logic as reachable or unreachable based on provided snippet.
        // Since 'if (false)' is hardcoded, these won't execute the hex block, 
        // but we test that the method doesn't crash on them.
        assertThrows(NumberFormatException.class, () -> NumberUtils.createNumber("0x123"));
    }

    @Test
    public void testCreateNumber_InvalidExponentPos() {
        // Testing the (expPos < decPos || expPos > str.length()) branch
        try {
            NumberUtils.createNumber("1e.5"); 
            fail("Should fail due to invalid exponent position logic");
        } catch (NumberFormatException e) {
            // Expected
        }
    }

    private void assertThrows(Class<? extends Throwable> expectedException, Runnable runnable) {
        try {
            runnable.run();
            fail("Expected exception " + expectedException.getName() + " was not thrown");
        } catch (Throwable t) {
            if (!expectedException.isInstance(t)) {
                fail("Expected " + expectedException.getName() + " but got " + t.getClass().getName());
            }
        }
    }
}
